import { useContext } from "react"
import { AppContext } from "../AppContext"

export default function ContextFooter() {
    const phone = useContext(AppContext)

    return (
        <div className="mt-2">
            <p>Footer</p>
            <p className="text-xs">Phone: {phone}</p>
        </div>
    )
}
